+    result.stdout = "model-only output-reference envelope, not stdout".into();
+    result.stdout_recent = Some("literal [truncated] Ω界\n".repeat(1000));
+    result.stderr_recent = Some("literal [timeout] Ω界\n".repeat(1000));
