+        drop(db.admit_user_shell_job(&p, false, None).unwrap());
+        let mut outcome = crate::shell::jobs::Outcome::unknown("fixture outcome");
+        outcome.state = "completed".into();
+        outcome.exit = Some(0);
+        outcome.stdout = "process output".into();
